{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table daniel_klein_db.maplemonk.daniel_klein_inventory_fact_items_by_mp as WITH daily_sku_sales AS ( SELECT CAST(order_date AS DATE) AS date_day, upper(sku) as sku, upper(data_source) as data_source, upper(ifnull(marketplace, data_source)) as marketplace, SUM(ifnull(quantity,0)) AS daily_quantity, SUM(ifnull(selling_price,0)) as total_sales from daniel_klein_db.MAPLEMONK.daniel_klein_db_sales_consolidated s WHERE upper(data_source) in (\'UNIWARE\') GROUP BY 1,2,3,4 ), daily_inventory_snapshot AS ( select date_day, sku, \'UNIWARE\' as data_source, cast(available_inventory as int) as inventory_that_day, CASE WHEN ifnull(cast(available_inventory as int),0) > 0 THEN 1 ELSE 0 END AS has_inventory, CASE WHEN ifnull(cast(available_inventory as int),0) < 4 THEN 1 ELSE 0 END AS is_oos from (select DATEADD(day, -1, CAST(left(_airbyte_emitted_at, 10) AS DATE)) as date_day, upper(\"Sku Code\") as sku, sum(cast(\"Total (Stock on hand)\" as int)) as available_inventory from daniel_klein_db.maplemonk.unicommerce_datatable_search_get_inventory_snapshot_export_full_refresh where type = \'GOOD_INVENTORY\' group by 1,2 ) ), all_distinct_entities AS ( SELECT DISTINCT sku, data_source, marketplace FROM daily_sku_sales UNION SELECT DISTINCT sku, data_source, \'UNASSIGNED_MARKETPLACE\' as marketplace FROM daily_inventory_snapshot i WHERE NOT EXISTS ( SELECT 1 FROM daily_sku_sales s WHERE s.sku = i.sku AND s.data_source = i.data_source ) ), all_sku_dates AS ( SELECT DISTINCT c.date_day, d.sku, d.data_source, d.marketplace FROM all_distinct_entities AS d CROSS JOIN ( SELECT DATEADD(day, SEQ4(), \'2026-05-01\'::DATE) AS date_day FROM TABLE(GENERATOR(ROWCOUNT => 10000)) WHERE DATEADD(day, SEQ4(), \'2026-05-01\'::DATE) <= CURRENT_DATE() ) AS c ), sales_metrics AS ( SELECT a.date_day, a.sku, a.data_source, a.marketplace, COALESCE(s.daily_quantity, 0) AS daily_quantity, COALESCE(s.total_sales, 0) as total_sales, COALESCE(i.has_inventory, 0) AS has_inventory_today, COALESCE(i.inventory_that_day, 0) as inventory_that_day, ifnull(i.is_oos, 1) AS is_oos_today, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS L7_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS L14_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS L30_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS L45_day_sales, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS inventory_days_7, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS inventory_days_14, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS inventory_days_30, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS inventory_days_45, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS oos_days_7, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS oos_days_14, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS oos_days_30, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku, a.data_source, a.marketplace ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS oos_days_45, CASE WHEN ROW_NUMBER() OVER(PARTITION BY a.date_day, a.sku, a.data_source ORDER BY a.marketplace) = 1 THEN 1 ELSE 0 END as is_first_mp_for_inventory FROM all_sku_dates AS a LEFT JOIN daily_sku_sales AS s ON a.date_day = s.date_day AND a.sku = s.sku AND a.data_source = s.data_source AND a.marketplace = s.marketplace LEFT JOIN daily_inventory_snapshot AS i ON a.date_day = i.date_day AND a.sku = i.sku AND a.data_source = i.data_source ) SELECT date_day as data_fetch_date, s.sku, s.data_source, s.marketplace, p.name as product_name, p.product_category, p.product_sub_category, p.bucket_1, p.bucket_2, s.total_sales, s.daily_quantity, s.has_inventory_today, s.inventory_that_day as available_inventory, CASE WHEN s.is_first_mp_for_inventory = 1 THEN s.inventory_that_day ELSE 0 END as non_duplicated_inventory, L7_day_sales sold_quantity_7_days, L14_day_sales sold_quantity_14_days, L30_day_sales sold_quantity_30_days, L45_day_sales sold_quantity_45_days, inventory_days_7, inventory_days_14, inventory_days_30, inventory_days_45, oos_days_7, oos_days_14, oos_days_30, oos_days_45, CASE WHEN data_source IN (\'UNIWARE\') THEN s.inventory_that_day ELSE 0 END AS mp_inventory FROM sales_metrics s LEFT JOIN (select upper(trim(dk_sku)) as sku, upper(trim(product_category)) as product_category, upper(trim(product_sub_category)) as product_sub_category, upper(trim(catalog_name)) as name, upper(trim(bucket_1)) as bucket_1, upper(trim(bucket_2)) as bucket_2 from DANIEL_KLEIN_DB.MAPLEMONK.Google_Sheet_SKU_MASTER qualify row_number() over (partition by upper(trim(dk_sku)) order by 1) = 1 ) p on upper(p.sku) = upper(s.sku) ORDER BY data_fetch_date DESC, sku, data_source, marketplace;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from DANIEL_KLEIN_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            